export const ROLE_ORDER = Object.keys(ROLES);
/** Whether a key (e.g. from ?position=) names one of the designations. */
export const isRole = key => typeof key === 'string' && Object.hasOwn(ROLES, key);
export const GROUP_ORDER = ['Operational', 'Growth', 'Executive'];
export const EXEC_NOTE = 'Every executive designation carries a three-month probationary period at 85% of the confirmed salary; PF, TDS, professional tax and gratuity accrual apply from Day 1 regardless of probation.';
export const EXEC_FOOTNOTE = 'All figures are gross/CTC monthly at the confirmed rate and remain illustrative pending legal and tax review. Employee versus independent-contractor classification, and the resulting tax treatment, is confirmed before any offer is issued.';

/** Every question of a role, in order. */
export const questionsOf = key => ROLES[key].groups.flatMap(g => g.questions);
export const questionCount = key => questionsOf(key).length;
export const requiredCount = key => questionsOf(key).filter(q => q.required).length;
/** The pay figure shown in the positions list. */
export const listPay = r => r.listPay || r.pay[0].value;

const CELLS = ['kpi', 'lean', 'over', 'tlean', 'tover'];
/** Every answer field a question owns, with its length limit. */
export function answerFields(q) {
  if (q.kind === 'pair') return [{ id: q.id, max: q.max }, { id: q.id2, max: q.max }];
  if (q.kind === 'table') return [...q.tableRows.flatMap(r => CELLS.map(c => ({ id: r[c], max: q.max }))), { id: q.noteId, max: q.noteMax }];
  return [{ id: q.id, max: q.max }];
}
/** Whether a required question is answered (a KPI table needs one row with a KPI, Lean and Over-target). */
export function isAnswered(q, a) {
  const v = id => String(a?.[id] ?? '').trim();
  if (q.kind === 'pair') return !!(v(q.id) && v(q.id2));
  if (q.kind === 'table') return q.tableRows.some(r => v(r.kpi) && v(r.lean) && v(r.over));
  return !!v(q.id);
}

export const NOTICE_OPTIONS = ['Immediately', '15 days', '30 days', '45 days', '60 days', '90 days', 'Other'];
export const CV_TYPES = { 'application/pdf': 'PDF', 'application/msword': 'DOC', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document': 'DOCX' };
export const CV_EXT = /\.(pdf|docx?)$/i;
export const CV_MAX = 10 * 1024 * 1024; // "PDF, DOC or DOCX (max 10 MB)"

/** The number without its country code or trunk 0, however it was typed ("+971 50…", "0091 98…", "098…", "050…"). */
export function nationalDigits(cc, phone) {
  const raw = String(phone || '').trim();
  const code = String(cc || '').replace(/\D/g, '');
  let d = raw.replace(/\D/g, '');
  if (raw.startsWith('00')) d = d.slice(2);                                    // 00 = international prefix
  if ((raw.startsWith('+') || raw.startsWith('00')) && code && d.startsWith(code)) d = d.slice(code.length);
  else if (code === '91' && d.length === 12 && d.startsWith('91')) d = d.slice(2);
  if (code !== '1') d = d.replace(/^0(?=\d{6})/, '');                          // trunk prefix, e.g. 098… / 050…
  return d;
}
